unit("순환", "중2 · 동물과 에너지",
 "소화된 영양소는 소장 융털의 모세 혈관과 암죽관으로 흡수된다.",
 "순환계는 심장, 혈관, 혈액으로 이루어져 영양소와 산소를 온몸의 세포에 나르고 이산화 탄소와 노폐물을 거두어 온다. 사람의 심장은 2개의 심방과 2개의 심실로 되어 있으며, 심방과 심실 사이, 심실과 동맥 사이의 판막이 혈액이 거꾸로 흐르지 않게 한다. 혈액은 동맥 → 모세 혈관 → 정맥 순서로 흐르는데, 동맥은 혈압이 높아 벽이 두껍고 탄력이 크며, 정맥은 혈압이 낮아 군데군데 판막이 있고, 모세 혈관은 벽이 한 층의 세포로 얇아 조직 세포와 물질 교환이 일어난다. 혈액은 액체 성분인 혈장과 세포 성분인 적혈구, 백혈구, 혈소판으로 이루어진다. 혈액 순환은 좌심실 → 대동맥 → 온몸의 모세 혈관 → 대정맥 → 우심방으로 이어지는 온몸 순환과, 우심실 → 폐동맥 → 폐의 모세 혈관 → 폐정맥 → 좌심방으로 이어지는 폐순환으로 나뉜다.",
 [("한 방향으로 흐르는 혈액", "심장과 정맥의 판막 덕분에 혈액은 심방 → 심실 → 동맥 → 모세 혈관 → 정맥 → 심방의 한 방향으로만 흐른다."),
  ("혈관 구조와 혈압", "혈압은 동맥 > 모세 혈관 > 정맥 순이다. 혈압이 높은 동맥은 벽이 두껍고, 혈압이 낮은 정맥은 판막으로 역류를 막는다."),
  ("두 갈래 순환", "온몸 순환은 조직 세포에 산소를 주고 이산화 탄소를 받아 오고, 폐순환은 폐에서 이산화 탄소를 내보내고 산소를 받아 온다.")],
 [I("심방", "정맥과 연결되어 심장으로 들어오는 혈액을 받아들이는 곳", "구조", "대정맥과 폐정맥의 혈액이 먼저 심장의 위쪽 두 방으로 들어온다."),
  I("심실", "동맥과 연결되어 혈액을 심장 밖으로 내보내는 곳으로 근육 벽이 두껍다", "구조", "심장 아래쪽 두 방이 수축하면 혈액이 동맥으로 뿜어져 나간다."),
  I("판막", "혈액이 거꾸로 흐르는 것을 막는 얇은 막", "구조", "청진기로 들리는 '쿵' 소리는 이 막이 닫히는 소리이다."),
  I("동맥", "심장에서 나가는 혈액이 흐르는 혈관으로, 벽이 두껍고 탄력이 크다", "구조", "손목에서 느껴지는 맥박은 이 혈관이 뛰는 것이다."),
  I("정맥", "심장으로 돌아오는 혈액이 흐르는 혈관으로, 혈압이 낮고 군데군데 판막이 있다", "구조", "손등에 보이는 푸르스름한 핏줄이 이 혈관이다."),
  I("모세 혈관", "벽이 한 층의 세포로 된 가는 혈관으로 조직 세포와 물질 교환이 일어난다", "구조", "온몸 곳곳에 그물처럼 퍼져 있어 거의 모든 세포 가까이 지나간다."),
  I("혈장", "혈액의 액체 성분으로 영양소, 이산화 탄소, 노폐물을 녹여 운반한다", "개념", "혈액을 원심 분리하면 위쪽에 연한 노란색 액체층이 생긴다."),
  I("적혈구", "헤모글로빈이 있어 산소를 운반하는 가운데가 오목한 원반 모양의 혈구", "구조", "혈액 속에 가장 많은 세포 성분으로, 혈액을 붉게 보이게 한다."),
  I("백혈구", "핵이 있고 모양이 일정하지 않으며 몸에 들어온 세균을 잡아먹는 혈구", "구조", "상처에 세균이 들어오면 그 수가 늘어나 염증 부위로 모인다."),
  I("혈소판", "상처가 났을 때 혈액을 응고시켜 피가 멎게 하는 작은 혈구 조각", "구조", "무릎이 까진 뒤 시간이 지나면 피가 굳어 딱지가 생긴다.")],
 [M("산소를 운반하는 혈액 성분은?", "", ["백혈구", "혈소판", "적혈구", "혈장"], 2, "적혈구의 헤모글로빈이 산소와 결합해 운반한다. 혈장은 영양소와 이산화 탄소 등을 운반한다.", 1),
  M("조직 세포와 혈액 사이에서 물질 교환이 일어나는 혈관은?", "", ["동맥", "모세 혈관", "정맥", "대동맥"], 1, "모세 혈관은 벽이 매우 얇아 물질 교환이 일어난다.", 1),
  M("심장과 정맥에서 혈액이 거꾸로 흐르는 것을 막는 구조는?", "", ["판막", "심방", "혈장", "융털"], 0, "판막은 한쪽 방향으로만 열려 혈액의 역류를 막는다.", 1),
  M("폐순환의 경로를 바르게 나타낸 것은?", "", ["좌심실 → 대동맥 → 폐 → 대정맥 → 우심방", "우심방 → 폐정맥 → 폐 → 폐동맥 → 좌심실", "좌심방 → 폐동맥 → 폐 → 폐정맥 → 우심실", "우심실 → 폐동맥 → 폐 → 폐정맥 → 좌심방"], 3, "폐순환은 우심실에서 나가 폐동맥, 폐의 모세 혈관, 폐정맥을 거쳐 좌심방으로 돌아온다.", 2),
  M("혈관의 혈압을 높은 순서대로 나열한 것은?", "", ["동맥 > 모세 혈관 > 정맥", "정맥 > 모세 혈관 > 동맥", "모세 혈관 > 동맥 > 정맥", "동맥 > 정맥 > 모세 혈관"], 0, "심장에서 바로 나온 동맥의 혈압이 가장 높고, 모세 혈관을 거치며 낮아져 정맥에서 가장 낮다.", 2),
  M("심장에서 근육 벽이 가장 두꺼운 곳과 그 까닭으로 옳은 것은?", "", ["우심방 – 온몸에서 오는 혈액을 받으므로", "좌심실 – 온몸으로 혈액을 강하게 내보내야 하므로", "우심실 – 폐로 혈액을 보내므로", "좌심방 – 폐에서 오는 혈액을 받으므로"], 1, "좌심실은 온몸 순환의 출발점이라 큰 힘이 필요해 벽이 가장 두껍다. 우심실은 가까운 폐로만 보내므로 상대적으로 얇다.", 2),
  M("자료를 보고 모세 혈관에 대해 옳게 설명한 것은?", "혈관 종류별 비교\n동맥: 총 단면적 작음, 혈류 속도 빠름\n모세 혈관: 총 단면적 가장 큼, 혈류 속도 가장 느림\n정맥: 총 단면적 중간, 혈류 속도 중간", ["혈류가 빨라 물질 교환이 거의 일어나지 않는다", "총 단면적이 가장 작아 혈압이 가장 높다", "판막이 많아 혈액이 느리게 흐른다", "혈액이 느리게 흘러 조직 세포와 물질 교환을 할 시간이 충분하다"], 3, "모세 혈관은 총 단면적이 커서 혈류가 가장 느리고, 그만큼 물질 교환이 충분히 일어난다. 판막은 정맥에 있다.", 3),
  M("산소를 많이 포함한 혈액이 흐르는 혈관끼리 짝 지은 것은?", "", ["폐동맥, 대정맥", "폐동맥, 대동맥", "폐정맥, 대동맥", "폐정맥, 대정맥"], 2, "폐에서 산소를 받은 혈액은 폐정맥 → 좌심방 → 좌심실 → 대동맥으로 흐른다. 폐동맥에는 산소가 적은 혈액이 흐르므로 이름만 보고 판단하면 틀린다.", 3)])

